const JOBS_URL='https://nexora-salon-job-portal.templateapp67.chatgpt.site/';
const BASE='https://fanal-templetes-app.vercel.app';
const SIGNUP_URL=BASE+'/templates';
const LOGIN_URL=BASE+'/templates';
const people=[['Customers','Your Next Beauty Experience Starts Here.',['Find services near you','Compare service menus, profiles and portfolios','Book slots and manage appointments','Discover offers and experiences','Earn rewards on eligible actions','Rebook your favourite professional'],'Explore Beauty Near You','discover','assets/spa.webp'],['Beauty Businesses','Your Business. Your Brand. Your Growth.',['Get a professional business presence','Explore beauty-specific website templates','Showcase services, prices, gallery and team','Become booking and enquiry ready','Build repeat customers with offers and rewards','Get local onboarding support'],'Create My Business Profile','business','salon.webp'],['Professionals','Turn Your Skill Into Opportunity.',['Build a professional profile','Display your portfolio and services','Explore jobs and freelance opportunities','Connect with beauty businesses','Build your professional reputation'],'Find Opportunities','jobs','assets/barber.webp'],['Suppliers & Brands','Reach the Beauty Businesses That Need You.',['Create a supplier storefront','Showcase catalogues and wholesale offerings','Receive business enquiries','Connect with salons, spas, clinics and academies','Grow your B2B visibility'],'Become a Supplier','marketplace','assets/products.webp'],['Growth Partners','Build Beauty Businesses. Build Your Future.',['Help local beauty businesses go digital','Onboard verified businesses','Unlock qualifying milestone rewards','Earn eligible performance-linked payouts','Explore district-level opportunities'],'Become a Growth Partner','growth-partner','assets/team.webp'],['Enterprise','Built for Ambitious Beauty Brands.',['Multi-location business management','Branded digital presence','Discovery and growth infrastructure','Custom onboarding','Enterprise support'],'Talk to Nexora Enterprise','contact','salon.webp']];
const event=(name,detail={})=>{window.dispatchEvent(new CustomEvent('nexora:analytics',{detail:{event:name,...detail}}));if(window.dataLayer)window.dataLayer.push({event:name,...detail})};
const btn=(label,href,cls='')=>`<a class="btn ${cls}" href="${/^\/jobs(?:\/|\?|$)/.test(href)?JOBS_URL:href}" data-event="cta_${label.toLowerCase().replace(/[^a-z0-9]+/g,'_')}">${label}<span aria-hidden="true">↗</span></a>`;
const checks=items=>`<ul class="check">${items.map(x=>`<li>${x}</li>`).join('')}</ul>`;
const audienceMarkup=(i=0)=>{const p=people[i];return `<div class="split"><div><span class="mini-tag">FOR ${p[0].toUpperCase()}</span><h2>${p[1]}</h2>${checks(p[2])}${btn(p[3],'/'+p[4]+'/')}</div><img src="/${p[5]}" class="rounded" loading="lazy" alt="${p[0]} in the beauty industry"></div>`};
const rewardProducts=[['tshirt','A white T-shirt, sample photo; final Nexora branding may differ'],['tablet','Samsung Galaxy Tab S9 tablet product photo'],['laptop','HP laptop product photo'],['scooter','Ather Rizta electric scooter product photo'],['iphone','Apple iPhone product photo'],['motorcycle','Royal Enfield Classic 350 motorcycle product photo'],['suv','Mahindra Scorpio-N SUV product photo']];
const route=location.pathname.split('/').filter(Boolean)[0]||'home';
// Client interaction setup
// Page HTML is already rendered: attach handlers without rebuilding the DOM.
if(route!=='home')document.title=`${route==='growth-partner'?'Growth Partner':route[0].toUpperCase()+route.slice(1)} | Nexora`;
const audience=(i=0)=>{document.getElementById('audience').innerHTML=audienceMarkup(i);document.getElementById('audience').setAttribute('aria-labelledby','tab-'+i);document.querySelectorAll('.tab').forEach((t,n)=>{t.setAttribute('aria-selected',n===i);t.tabIndex=n===i?0:-1})};
const toast=(s)=>{document.querySelector('.toast')?.remove();const t=document.createElement('div');t.className='toast';t.setAttribute('role','status');t.textContent=s;document.body.append(t);setTimeout(()=>t.remove(),5000)};
const modal=document.getElementById('modal');
function contact(){modal.innerHTML=`<button class="close" aria-label="Close dialog">×</button><div class="eyebrow">NEXORA ASSISTANT</div><h2>Let’s Find Your Path.</h2><p>Choose a topic to continue on the Nexora platform. No phone number needed.</p><label class="field">I’m interested in<select id="contact-topic"><option value="/templates">Business setup</option><option value="/templates">Website templates</option><option value="/partner">Growth Partner</option><option value="/templates">Enterprise</option></select></label><a class="btn" id="contact-next" href="${SIGNUP_URL}">Continue to Nexora ↗</a>`;modal.showModal();document.getElementById('contact-topic').onchange=e=>document.getElementById('contact-next').href=BASE+e.target.value}
function interest(topic){modal.innerHTML=`<button class="close" aria-label="Close dialog">×</button><span class="mini-tag">${topic}</span><h2>Your Next Opportunity.</h2><p>Save your interest on this device, then create your Nexora account. This form does not send an application or register you for email updates.</p><form id="interest-form"><label class="field">Your name<input name="name" required minlength="2" maxlength="80" autocomplete="name"></label><label class="field">Email address<input name="email" type="email" required maxlength="150" autocomplete="email"></label><label style="font-size:12px"><input type="checkbox" name="consent" required> Save these details on this device.</label><p class="error" id="form-error" role="alert"></p><button class="btn">Save Interest on This Device ↗</button></form><p class="note">Already have an account? <a class="link" href="${LOGIN_URL}">Log in</a></p>`;modal.showModal();document.getElementById('interest-form').onsubmit=e=>{e.preventDefault();const data=new FormData(e.target);const name=data.get('name').trim();if(name.length<2){document.getElementById('form-error').textContent='Please enter at least two characters for your name.';return}try{const existing=JSON.parse(localStorage.getItem('nexora-interests')||'[]');existing.push({name,email:data.get('email').trim(),topic,date:new Date().toISOString()});localStorage.setItem('nexora-interests',JSON.stringify(existing));modal.close();toast('Interest saved on this device. Complete enrolment on Nexora.');event('interest_saved_local',{topic})}catch{document.getElementById('form-error').textContent='Device storage is unavailable. Create your Nexora account to continue.'}}}
document.addEventListener('click',e=>{const target=e.target.closest('[data-event],[data-contact],[data-interest],[data-reward],[data-tab],.close,.menu,[data-filter],[data-template-category]');if(!target)return;if(target.dataset.event)event(target.dataset.event);if(target.matches('.menu')){const open=document.querySelector('.navlinks').classList.toggle('open');target.setAttribute('aria-expanded',open);target.textContent=open?'×':'☰'}if(target.matches('.close'))modal.close();if(target.hasAttribute('data-contact'))contact();if(target.hasAttribute('data-interest'))interest(target.dataset.interest);if(target.hasAttribute('data-tab')){audience(Number(target.dataset.tab));event('audience_tab',{audience:people[target.dataset.tab][0]})}if(target.hasAttribute('data-reward')){const i=Number(target.dataset.reward);const names=['Official Nexora T-Shirt','Samsung Tablet','Branded HP Laptop','Electric Scooter','Latest iPhone','Royal Enfield 350 cc','SUV Car Reward'];modal.innerHTML=`<button class="close" aria-label="Close product photo">×</button><span class="mini-tag">REWARD PRODUCT PHOTO</span><h2>${names[i]}</h2><img class="reward-enlarged" src="/assets/rewards/${rewardProducts[i][0]}.webp" alt="${rewardProducts[i][1]}"><p class="note">${i===0?'Sample T-shirt photo. Final Nexora branding and design may differ.':'Representative product photo. Final reward model and colour depend on program terms and availability.'}</p>`;modal.showModal();event('reward_photo_preview',{product:rewardProducts[i][0]})}if(target.hasAttribute('data-filter')){document.querySelectorAll('[data-filter]').forEach(b=>b.classList.toggle('selected',b===target));document.querySelectorAll('#discover-grid .card').forEach(c=>c.hidden=target.dataset.filter!=='all'&&c.dataset.category!==target.dataset.filter)}});
document.querySelector('.tabs')?.addEventListener('keydown',e=>{const t=e.target.closest('[data-tab]');if(!t)return;let i=Number(t.dataset.tab);if(e.key==='ArrowRight')i=(i+1)%people.length;else if(e.key==='ArrowLeft')i=(i+people.length-1)%people.length;else if(e.key==='Home')i=0;else if(e.key==='End')i=people.length-1;else return;e.preventDefault();audience(i);document.getElementById('tab-'+i).focus()});
modal.addEventListener('click',e=>{if(e.target===modal){const r=modal.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)modal.close()}});
function search(input,grid,empty){document.getElementById(input)?.addEventListener('input',e=>{let count=0;document.querySelectorAll('#'+grid+' [data-name]').forEach(c=>{c.hidden=!c.dataset.name.includes(e.target.value.toLowerCase().trim());if(!c.hidden)count++});document.getElementById(empty).hidden=count>0;event('directory_search',{directory:grid})})}search('job-search','job-grid','job-empty');search('market-search','market-grid','market-empty');
document.getElementById('discover-search')?.addEventListener('submit',e=>{e.preventDefault();const d=new FormData(e.target);const q=d.get('service').toLowerCase().trim();let count=0;document.querySelectorAll('#discover-grid .card').forEach(c=>{c.hidden=!!q&&!c.textContent.toLowerCase().includes(q);if(!c.hidden)count++});document.getElementById('search-result').textContent=count?`${count} illustrative categories match. City availability is checked on the Nexora platform.`:'No matching categories. Try hair, barber, spa, nails or tattoo.';event('discover_search',{city:d.get('city')})});
document.getElementById('collection')?.addEventListener('input',e=>{const n=Number(e.target.value);document.getElementById('calculation').textContent=Number.isFinite(n)&&n>=0?'Illustrative partner payout: '+new Intl.NumberFormat('en-IN',{style:'currency',currency:'INR'}).format(n*.1*.1):'Enter a valid non-negative amount.'});
document.getElementById('clear-interest')?.addEventListener('click',()=>{localStorage.removeItem('nexora-interests');toast('Device-saved interests deleted.')});
const params=new URLSearchParams(location.search);if(route==='policies'&&params.get('section')){const el=document.getElementById(params.get('section'));if(el){el.open=true;el.scrollIntoView()}}if(route==='jobs'&&params.get('role')){const input=document.getElementById('job-search');input.value=params.get('role');input.dispatchEvent(new Event('input'))}if(route==='marketplace'&&params.get('category')){const input=document.getElementById('market-search');input.value=params.get('category');input.dispatchEvent(new Event('input'))}if(route==='jobs'&&params.get('action')==='post')interest('Recruiter');if(route==='marketplace'&&params.get('action')==='sell')interest('Supplier');

let templateCategory='all';
function filterTemplates(){const q=(document.getElementById('template-search')?.value||'').trim().toLowerCase();let count=0;document.querySelectorAll('#template-grid [data-template-id]').forEach(c=>{const visible=(templateCategory==='all'||c.dataset.category===templateCategory||c.dataset.vip==='true')&&c.dataset.name.includes(q);c.hidden=!visible;if(visible)count++});const total=document.querySelectorAll('#template-grid [data-template-id]').length;document.getElementById('template-count').textContent=`Showing ${count} of ${total} live templates`;document.getElementById('template-empty').hidden=count>0;}
document.getElementById('template-search')?.addEventListener('input',filterTemplates);
document.getElementById('template-filter')?.addEventListener('click',e=>{const b=e.target.closest('[data-template-category]');if(!b)return;templateCategory=b.dataset.templateCategory;document.querySelectorAll('[data-template-category]').forEach(t=>{t.classList.toggle('selected',t===b);t.setAttribute('aria-pressed',t===b)});filterTemplates();event('template_category',{category:templateCategory})});
